const $=s=>document.getElementById(s);function draw(){let v=DATA.indices[$('idx').value],a=DATA.dates.findIndex(d=>d>=$('from').value),b=DATA.dates.findLastIndex(d=>d<=$('to').value),def=$('def').value;if(a<0||b<a){$('plots').textContent='日期范围没有数据';$('rows').innerHTML='';$('counts').textContent='';return}let ls=v.labels.filter(l=>l.i>=a&&l.i<=b&&(def==='both'||def===l.definition));$('counts').textContent=v.name+'：当前范围 '+ls.filter(l=>l.direction==='TOP').length+' 个顶 / '+ls.filter(l=>l.direction==='BOTTOM').length+' 个底（两种口径同时显示时分别计数）';$('plots').innerHTML=[5,9].map(scale=>{let labels=ls.filter(l=>l.scale===scale),ps=v.close.slice(a,b+1).concat(labels.map(l=>+l.pivot_price)),lo=Math.min(...ps)*.98,hi=Math.max(...ps)*1.02,x=i=>65+(i-a)/Math.max(1,b-a)*1450,y=p=>330-(p-lo)/(hi-lo)*265;let s='<svg viewBox="0 0 1550 375" role="img" aria-label="'+v.name+scale+'%顶底"><text x="65" y="30" font-size="20">'+v.name+' · '+scale+'%波段</text>';for(let j=0;j<5;j++){let p=lo+(hi-lo)*j/4,yy=y(p);s+='<path d="M65 '+yy+' H1515" stroke="#e6ebf1"/><text x="8" y="'+(yy+4)+'" font-size="12">'+p.toFixed(0)+'</text>'}s+='<path d="'+v.close.slice(a,b+1).map((p,j)=>(j?'L':'M')+x(j+a).toFixed(2)+','+y(p).toFixed(2)).join(' ')+'" fill="none" stroke="#718199" stroke-width="1.4"/>';labels.forEach(l=>{let xx=x(l.i),yy=y(+l.pivot_price),top=l.direction==='TOP',dy=top?-10:10,c=top?'#d33f49':'#078775',solid=l.definition!=='close';s+='<polygon tabindex="0" data-tip="'+[l.pivot_date,scale+'% '+(top?'顶':'底')+' '+l.pivot_price,solid?'盘中极值 / 收盘确认':'收盘价',l.confirmation_date+' 收盘确认'].join('&#10;')+'" points="'+xx+','+yy+' '+(xx-6)+','+(yy+dy)+' '+(xx+6)+','+(yy+dy)+'" fill="'+(solid?c:'white')+'" stroke="'+c+'" stroke-width="1.5"/>'});for(let j=0;j<=6;j++){let i=Math.round(a+(b-a)*j/6);s+='<text x="'+(x(i)-30)+'" y="355" font-size="12">'+DATA.dates[i]+'</text>'}return s+'</svg>'}).join('');$('rows').innerHTML=ls.slice().sort((a,b)=>a.i-b.i||a.scale-b.scale).map(l=>'<tr><td>'+l.scale+'%</td><td>'+(l.definition==='close'?'收盘':'盘中极值')+'</td><td>'+(l.direction==='TOP'?'顶':'底')+'</td><td>'+l.pivot_date+'</td><td>'+l.pivot_price+'</td><td>'+l.confirmation_date+'</td></tr>').join('');document.querySelectorAll('[data-tip]').forEach(el=>{el.onmousemove=e=>{let t=$('tip');t.textContent=el.dataset.tip;t.style.display='block';t.style.left=Math.min(e.clientX+15,innerWidth-260)+'px';t.style.top=Math.max(0,e.clientY-95)+'px'};el.onmouseleave=()=>{$('tip').style.display='none'}})}['idx','def','from','to'].forEach(id=>$(id).onchange=draw);$('all').onclick=()=>{$('from').value=DATA.dates[0];$('to').value=DATA.dates.at(-1);draw()};$('recent').onclick=()=>{$('from').value='2023-08-25';$('to').value=DATA.dates.at(-1);draw()};draw();